// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {ERC20} from "./vendor/ERC20.sol";
import {IERC20Minimal} from "./interfaces/IUniswapV3.sol";

interface IRhFeeSink {
    function minHolderDistribute() external view returns (uint256);
    function minHolderDistributeUsd6() external view returns (uint256);
    function rewardUsd6(address pairAsset, uint256 amount) external view returns (uint256);
    function weth() external view returns (address);
}

/// @notice Fixed 1B supply. No transfer tax. Liquidity sits in official Uniswap v4.
///         Holder-mode pair fees sit in this contract until the pot is worth
///         at least the factory USD floor, then they are pushed to current holders.
contract RhLaunchToken is ERC20 {
    enum FeeTo {
        Creator,
        Holders
    }

    uint256 public constant TOTAL_SUPPLY = 1_000_000_000e18;
    uint256 public constant MAX_PAYOUTS_PER_TX = 100;

    address public immutable factory;
    address public immutable creator;
    address public immutable pairAsset;
    uint16 public immutable creatorFeeBps;
    FeeTo public immutable feeTo;

    string public image;
    string public description;
    string public twitter;
    string public telegram;
    string public website;
    bool public metadataFrozen;

    address public pool;
    address public vault;

    uint256 public holderPairPot;
    uint256 public distributingPot;
    uint256 public distributingPaid;
    uint256 public distributingCirc;
    uint256 public distributeCursor;
    mapping(address => uint256) public claimablePair;

    address[] public holders;
    mapping(address => uint256) public holderIndex;

    error NotFactory();
    error NotVault();
    error ZeroAddress();
    error MetadataFrozen();
    error NothingToClaim();
    error PoolAlreadySet();
    error VaultAlreadySet();
    error Reentrant();

    event PoolBound(address pool);
    event VaultBound(address vault);
    event HoldersDistributed(uint256 amount, uint256 circulating);
    event PairPaid(address indexed account, uint256 amount);
    event PairClaimed(address indexed account, uint256 amount);

    uint256 private locked = 1;

    modifier onlyFactory() {
        if (msg.sender != factory) revert NotFactory();
        _;
    }

    modifier nonReentrant() {
        if (locked != 1) revert Reentrant();
        locked = 2;
        _;
        locked = 1;
    }

    constructor(
        string memory name_,
        string memory symbol_,
        address factory_,
        address creator_,
        address pairAsset_,
        uint16 creatorFeeBps_,
        FeeTo feeTo_
    ) ERC20(name_, symbol_) {
        if (factory_ == address(0) || creator_ == address(0)) revert ZeroAddress();
        factory = factory_;
        creator = creator_;
        pairAsset = pairAsset_;
        creatorFeeBps = creatorFeeBps_;
        feeTo = feeTo_;
        _mint(factory_, TOTAL_SUPPLY);
    }

    function setMetadata(
        string calldata image_,
        string calldata description_,
        string calldata twitter_,
        string calldata telegram_,
        string calldata website_
    ) external onlyFactory {
        if (metadataFrozen) revert MetadataFrozen();
        metadataFrozen = true;
        image = image_;
        description = description_;
        twitter = twitter_;
        telegram = telegram_;
        website = website_;
    }

    function imageUri() external view returns (string memory) {
        return image;
    }

    function bindPool(address pool_) external onlyFactory {
        if (pool != address(0)) revert PoolAlreadySet();
        if (pool_ == address(0)) revert ZeroAddress();
        pool = pool_;
        _dropHolder(pool_);
        emit PoolBound(pool_);
    }

    function bindVault(address vault_) external onlyFactory {
        if (vault != address(0)) revert VaultAlreadySet();
        if (vault_ == address(0)) revert ZeroAddress();
        vault = vault_;
        emit VaultBound(vault_);
    }

    function circulatingSupply() public view returns (uint256) {
        uint256 lockedBal = _balances[factory] + _balances[address(this)];
        if (pool != address(0)) lockedBal += _balances[pool];
        if (lockedBal >= TOTAL_SUPPLY) return 0;
        return TOTAL_SUPPLY - lockedBal;
    }

    function rewardAsset() public view returns (address) {
        if (pairAsset != address(0)) return pairAsset;
        return IRhFeeSink(factory).weth();
    }

    function holderCount() external view returns (uint256) {
        return holders.length;
    }

    function pendingPair(address account) public view returns (uint256) {
        uint256 owed = account == creator ? claimablePair[account] : 0;
        if (_excluded(account)) return owed;
        uint256 pot = holderPairPot + distributingPot;
        uint256 circ = circulatingSupply();
        if (pot == 0 || circ == 0) return owed;
        return owed + (_balances[account] * pot) / circ;
    }

    function notifyPairReward(uint256 amount) external nonReentrant {
        if (msg.sender != vault) revert NotVault();
        if (amount == 0) return;
        holderPairPot += amount;
        _tryDistribute();
    }

    /// @notice Anyone can poke this. Starts a push once the pot is ≥ $50 (factory floor)
    ///         and continues leftover batches if a prior push hit the per-tx cap.
    function distribute() external nonReentrant {
        _tryDistribute();
    }

    function claimPair() external nonReentrant {
        uint256 leftover = claimablePair[msg.sender];
        if (leftover == 0) revert NothingToClaim();
        claimablePair[msg.sender] = 0;
        IERC20Minimal(rewardAsset()).transfer(msg.sender, leftover);
        emit PairClaimed(msg.sender, leftover);
    }

    function _transfer(address from, address to, uint256 value) internal override {
        super._transfer(from, to, value);
        _syncHolder(from);
        _syncHolder(to);
    }

    function _tryDistribute() private {
        if (distributingPot != 0) {
            _push();
            return;
        }
        uint256 pot = holderPairPot;
        if (!_ready(pot)) return;
        uint256 circ = circulatingSupply();
        if (circ == 0) {
            claimablePair[creator] += pot;
            holderPairPot = 0;
            return;
        }
        holderPairPot = 0;
        distributingPot = pot;
        distributingPaid = 0;
        distributingCirc = circ;
        distributeCursor = 0;
        emit HoldersDistributed(pot, circ);
        _push();
    }

    function _ready(uint256 pot) private view returns (bool) {
        if (pot == 0) return false;
        IRhFeeSink sink = IRhFeeSink(factory);
        if (pot < sink.minHolderDistribute()) return false;
        uint256 minUsd = sink.minHolderDistributeUsd6();
        if (minUsd == 0) return true;
        uint256 usd = sink.rewardUsd6(pairAsset, pot);
        return usd != 0 && usd >= minUsd;
    }

    function _push() private {
        uint256 pot = distributingPot;
        uint256 circ = distributingCirc;
        if (pot == 0 || circ == 0) return;

        address reward = rewardAsset();
        uint256 n = holders.length;
        uint256 cursor = distributeCursor;
        uint256 end = cursor + MAX_PAYOUTS_PER_TX;
        if (end > n) end = n;
        uint256 paid;

        for (uint256 i = cursor; i < end; ++i) {
            address account = holders[i];
            if (_excluded(account)) continue;
            uint256 share = (_balances[account] * pot) / circ;
            if (share == 0) continue;
            if (_pay(reward, account, share)) {
                paid += share;
                emit PairPaid(account, share);
            }
        }

        distributingPaid += paid;
        distributeCursor = end;
        if (end < n) return;

        uint256 leftover = pot - distributingPaid;
        distributingPot = 0;
        distributingPaid = 0;
        distributingCirc = 0;
        distributeCursor = 0;
        if (leftover != 0) holderPairPot += leftover;
    }

    function _syncHolder(address account) private {
        if (_excluded(account)) {
            _dropHolder(account);
            return;
        }
        if (_balances[account] == 0) {
            _dropHolder(account);
            return;
        }
        if (holderIndex[account] != 0) return;
        holders.push(account);
        holderIndex[account] = holders.length;
    }

    function _dropHolder(address account) private {
        uint256 idx = holderIndex[account];
        if (idx == 0) return;
        uint256 last = holders.length;
        address tail = holders[last - 1];
        if (idx != last) {
            holders[idx - 1] = tail;
            holderIndex[tail] = idx;
        }
        holders.pop();
        holderIndex[account] = 0;
    }

    function _excluded(address account) private view returns (bool) {
        return account == address(0) || account == factory || account == pool || account == address(this);
    }

    function _pay(address token, address to, uint256 amount) private returns (bool) {
        (bool ok, bytes memory ret) = token.call(abi.encodeWithSelector(IERC20Minimal.transfer.selector, to, amount));
        if (!ok) return false;
        if (ret.length != 0 && !abi.decode(ret, (bool))) return false;
        return true;
    }
}

